CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS railway_stations(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL,station_code TEXT,city TEXT,district TEXT,state TEXT,latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL,railway_zone TEXT,source TEXT NOT NULL,source_id TEXT,verified BOOLEAN NOT NULL DEFAULT false,geom geography(Point,4326) GENERATED ALWAYS AS (ST_SetSRID(ST_MakePoint(longitude,latitude),4326)::geography) STORED,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source,source_id));
CREATE TABLE IF NOT EXISTS railway_gates(id BIGSERIAL PRIMARY KEY,name TEXT,gate_number TEXT,latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL,crossing_type TEXT,barrier_type TEXT,road_name TEXT,railway_line TEXT,nearby_station_id BIGINT REFERENCES railway_stations(id) ON DELETE SET NULL,source TEXT NOT NULL,source_id TEXT,verified BOOLEAN NOT NULL DEFAULT false,geom geography(Point,4326) GENERATED ALWAYS AS (ST_SetSRID(ST_MakePoint(longitude,latitude),4326)::geography) STORED,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source,source_id));
CREATE TABLE IF NOT EXISTS railway_crossings(id BIGSERIAL PRIMARY KEY,name TEXT,latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL,crossing_type TEXT,source TEXT NOT NULL,source_id TEXT,verified BOOLEAN NOT NULL DEFAULT false,geom geography(Point,4326) GENERATED ALWAYS AS (ST_SetSRID(ST_MakePoint(longitude,latitude),4326)::geography) STORED,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source,source_id));
CREATE TABLE IF NOT EXISTS railway_tracks(id BIGSERIAL PRIMARY KEY,railway_line TEXT,geometry geometry(Geometry,4326),source TEXT NOT NULL,source_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS trains(id BIGSERIAL PRIMARY KEY,train_number TEXT NOT NULL UNIQUE,train_name TEXT,origin TEXT,destination TEXT);
CREATE TABLE IF NOT EXISTS train_positions(id BIGSERIAL PRIMARY KEY,train_id BIGINT NOT NULL REFERENCES trains(id) ON DELETE CASCADE,latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL,speed DOUBLE PRECISION,heading DOUBLE PRECISION,current_station TEXT,next_station TEXT,delay INTEGER,timestamp TIMESTAMPTZ NOT NULL,source TEXT NOT NULL,live BOOLEAN NOT NULL DEFAULT false,geom geography(Point,4326) GENERATED ALWAYS AS (ST_SetSRID(ST_MakePoint(longitude,latitude),4326)::geography) STORED);
CREATE TABLE IF NOT EXISTS train_schedules(id BIGSERIAL PRIMARY KEY,train_id BIGINT NOT NULL REFERENCES trains(id) ON DELETE CASCADE,station_id BIGINT NOT NULL REFERENCES railway_stations(id) ON DELETE CASCADE,arrival_time TIMESTAMPTZ,departure_time TIMESTAMPTZ,sequence INTEGER NOT NULL,running_days TEXT);
CREATE TABLE IF NOT EXISTS gate_status(id BIGSERIAL PRIMARY KEY,gate_id BIGINT NOT NULL REFERENCES railway_gates(id) ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN ('OPEN','CLOSED','WARNING','UNKNOWN')),source TEXT,timestamp TIMESTAMPTZ NOT NULL DEFAULT now(),confidence TEXT);
CREATE INDEX IF NOT EXISTS railway_stations_geom_gix ON railway_stations USING GIST(geom);
CREATE INDEX IF NOT EXISTS railway_gates_geom_gix ON railway_gates USING GIST(geom);
CREATE INDEX IF NOT EXISTS railway_crossings_geom_gix ON railway_crossings USING GIST(geom);
CREATE INDEX IF NOT EXISTS railway_tracks_geom_gix ON railway_tracks USING GIST(geometry);
CREATE INDEX IF NOT EXISTS train_positions_geom_gix ON train_positions USING GIST(geom);
CREATE INDEX IF NOT EXISTS train_positions_timestamp_idx ON train_positions(timestamp DESC);
